import { FC } from 'react';
import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';

import type { CardProps } from 'antd';
import { Card, Flex, Typography } from 'antd';

import coinIcon from 'assets/images/coin.webp';
import { useStatisticsChartListQuery } from 'entities/Report';
import { EFilters } from 'features/Filters';
import { EMainRoutes, EYmPageScreen } from 'shared/typings';
import { OverlayLoader } from 'shared/ui';
import { formatDate, formatNumber, sendYmEvent } from 'shared/utils';

interface ILastProfitProps extends Partial<CardProps> {
	pageScreen?: EYmPageScreen;
	channelId?: string;
	isDashboard?: boolean;
}

export const LastProfit: FC<ILastProfitProps> = ({
	pageScreen = EYmPageScreen.CHANNEL_DETAIL_SCREEN,
	channelId,
	isDashboard = false,
	...props
}) => {
	const { t } = useTranslation();

	const dateAfter = new Date();
	const dateBefore = new Date();
	dateAfter.setHours(0, 0, 0, 0);
	dateBefore.setHours(0, 0, 0, 0);
	dateAfter.setDate(dateAfter.getDate() - 30);

	const { data, isFetching } = useStatisticsChartListQuery({
		[EFilters.AGGREGATE_BY]: 'day',
		[EFilters.DATE_AFTER]: `${formatDate(dateAfter, 'iso')}`,
		[EFilters.DATE_BEFORE]: `${formatDate(dateBefore, 'iso')}`,
		[EFilters.CHANNEL]: channelId ? [channelId] : undefined,
	});

	return (
		<Card {...props} variant="borderless" styles={{ body: { padding: '12px' } }}>
			{isFetching && <OverlayLoader />}

			<Flex align="center" justify="space-between">
				<Flex vertical gap={4}>
					<Flex gap={4} align="center">
						<img src={coinIcon} width={22} alt="coin" />
						<Typography.Text strong style={{ fontSize: 18 }}>
							{formatNumber(data?.reduce((acc, item) => acc + Number(item.amount), 0) || 0)} РУБ
						</Typography.Text>
					</Flex>

					<Typography.Text type="secondary" style={{ fontSize: 12 }}>
						{t('Заработано за последние 30 дней')}
					</Typography.Text>
				</Flex>

				{isDashboard && (
					<Link
						to={`/${EMainRoutes.FINANCES}`}
						onClick={() => sendYmEvent('click_finance', { page_screen: pageScreen })}
						type="link">
						{t('Финансы')}
					</Link>
				)}
			</Flex>
		</Card>
	);
};
